import { DevotionalPlan } from "@/types/devotionalPlan";

function makeDay(
  day: number,
  title: string,
  reference: string,
  reflection: string,
  question: string,
  prayer: string,
  practice: string,
) {
  return {
    day,
    title,
    reference: `${reference} · NTV`,
    verse: `Lectura base: ${reference} en Nueva Traducción Viviente`,
    reflection,
    question,
    prayer,
    practice,
  };
}

